// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Human-like mouse, keys and scroll through real input events
// Flo: curved mouse path in small steps > press + release with pauses > one key at a time with random gaps > scroll in chunks
// I/O: Page + Rng + Conf + text or point (caller) > CDP Input events (trusted browser events, no script clicks)
// ===================================================================
const std = @import("std"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .step_lo = 4, .step_hi = 16, .down_lo = 60, .down_hi = 180, .up_lo = 40, .up_hi = 110, .thnk_lo = 300, .thnk_hi = 900, .thnk_evy = 14, .spac_add = 60, .whel_lo = 60, .whel_hi = 140, .whel_gap = 40 };
pub const Env = struct { page: *pg.Page, rng: *pace.Rng, conf: cfgz.Conf, aren: std.mem.Allocator };
fn wait(env: *Env, lo: u64, hi: u64) void { env.page.nap(@intCast(pace.scaled(pace.logn(env.rng, lo, hi), env.conf.time_scal_perc))); }
fn mouse(env: *Env, kind: []const u8, xpos: f64, ypos: f64, down: bool) !void { const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .type = kind, .x = xpos, .y = ypos, .button = if (down or std.mem.eql(u8, kind, "mouseReleased")) "left" else "none", .clickCount = @as(u8, if (down or std.mem.eql(u8, kind, "mouseReleased")) 1 else 0) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchMouseEvent", prm); }
pub fn moveTo(env: *Env, tx: f64, ty: f64) !void { const sx = env.page.mx; const sy = env.page.my; const jit = (env.rng.unit() - 0.5) * 120.0; const cx = (sx + tx) / 2.0 + jit; const cy = (sy + ty) / 2.0 - jit; const cnt = env.conf.mous_step_coun; var idx: u32 = 1; while (idx <= cnt) : (idx += 1) { const tpp = @as(f64, @floatFromInt(idx)) / @as(f64, @floatFromInt(cnt)); const omt = 1.0 - tpp; const px = omt * omt * sx + 2.0 * omt * tpp * cx + tpp * tpp * tx; const py = omt * omt * sy + 2.0 * omt * tpp * cy + tpp * tpp * ty; try mouse(env, "mouseMoved", px, py, false); wait(env, CF.step_lo, CF.step_hi); } env.page.mx = tx; env.page.my = ty; }
pub fn click(env: *Env, tx: f64, ty: f64) !void { try moveTo(env, tx, ty); wait(env, CF.down_lo, CF.down_hi); try mouse(env, "mousePressed", tx, ty, true); wait(env, CF.up_lo, CF.up_hi); try mouse(env, "mouseReleased", tx, ty, true); }
pub fn pressKey(env: *Env, name: []const u8) !void { const isen = std.mem.eql(u8, name, "Enter"); const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = name, .code = name, .windowsVirtualKeyCode = @as(u32, if (isen) 13 else 27), .text = @as([]const u8, if (isen) "\r" else "") }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", prm); const upz = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = name, .code = name, .windowsVirtualKeyCode = @as(u32, if (isen) 13 else 27) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", upz); }
fn keyChar(env: *Env, chr: u8) !void { var one: [1]u8 = .{chr}; const down = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = @as([]const u8, &one), .text = @as([]const u8, &one) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", down); const upz = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = @as([]const u8, &one) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", upz); }
fn insChar(env: *Env, txt: []const u8) !void { const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .text = txt }, .{}); _ = try env.page.call(env.aren, "Input.insertText", prm); }
pub fn typeText(env: *Env, text: []const u8) !void { var idx: usize = 0; var cnt: u32 = 0; while (idx < text.len) { const lenz = std.unicode.utf8ByteSequenceLength(text[idx]) catch 1; const end = @min(idx + lenz, text.len); const sli = text[idx..end]; if (sli.len == 1 and sli[0] >= 32 and sli[0] < 127) { try keyChar(env, sli[0]); } else if (sli.len == 1 and sli[0] == '\n') { try pressKey(env, "Enter"); } else { try insChar(env, sli); } cnt += 1; wait(env, env.conf.type_dely_msec[0], env.conf.type_dely_msec[1]); if (sli.len == 1 and sli[0] == ' ') wait(env, CF.spac_add, CF.spac_add * 3); if (cnt % CF.thnk_evy == 0) wait(env, CF.thnk_lo, CF.thnk_hi); idx = end; } }
pub fn clearField(env: *Env) !void { const dwn = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = "a", .code = "KeyA", .windowsVirtualKeyCode = @as(u32, 65), .modifiers = @as(u32, 2), .commands = [_][]const u8{"selectAll"} }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", dwn); const upz = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = "a", .code = "KeyA", .windowsVirtualKeyCode = @as(u32, 65), .modifiers = @as(u32, 2) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", upz); wait(env, CF.up_lo, CF.up_hi); const bkd = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = "Backspace", .code = "Backspace", .windowsVirtualKeyCode = @as(u32, 8) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", bkd); const bku = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = "Backspace", .code = "Backspace", .windowsVirtualKeyCode = @as(u32, 8) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", bku); }
pub fn scrollBy(env: *Env, total: f64) !void { var done: f64 = 0; const sign: f64 = if (total < 0) -1.0 else 1.0; while (done < @abs(total)) { const chunk: f64 = @floatFromInt(env.rng.span(CF.whel_lo, CF.whel_hi)); const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "mouseWheel", .x = env.page.mx + 5.0, .y = env.page.my + 5.0, .deltaX = @as(f64, 0), .deltaY = chunk * sign }, .{}); _ = try env.page.call(env.aren, "Input.dispatchMouseEvent", prm); done += chunk; wait(env, CF.whel_gap, CF.whel_gap * 3); } }
